pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testRegression_property() public {
        address log = address(new LogFile());
        vm.prank(address(this));
        c.SetLogFile(log);
        vm.prank(address(this));
        c.SetMinSum(1);
        vm.prank(address(this));
        c.Initialized();
        address actor = address(0x123);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
